import{_ as e,o as s,c as a,ag as o}from"./chunks/framework.DB9Ll7VW.js";const u=JSON.parse('{"title":"Install Sikshya","description":"Install the free Sikshya LMS plugin (and Sikshya Pro) on your WordPress site, then confirm everything is working.","frontmatter":{"title":"Install Sikshya","description":"Install the free Sikshya LMS plugin (and Sikshya Pro) on your WordPress site, then confirm everything is working."},"headers":[],"relativePath":"installation.md","filePath":"installation.md","lastUpdated":1778327862000}'),i={name:"installation.md"};function r(n,t,l,d,c,h){return s(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="install-sikshya" tabindex="-1">Install Sikshya <a class="header-anchor" href="#install-sikshya" aria-label="Permalink to &quot;Install Sikshya&quot;">​</a></h1><p>You install Sikshya LMS the same way you install any WordPress plugin — there is <strong>no SaaS to sign up for</strong>. Sikshya runs entirely on your own site.</p><p><strong>First time in WordPress?</strong> After you activate the plugin, open <strong>Sikshya</strong> in the left sidebar and use <a href="/docs/admin-dashboard">Your WordPress admin (Sikshya)</a> as a plain-English map of every section.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Make sure your site meets these:</p><table tabindex="0"><thead><tr><th>What</th><th>Minimum</th><th>Recommended</th></tr></thead><tbody><tr><td>WordPress</td><td>6.0</td><td>6.4 or newer</td></tr><tr><td>PHP</td><td>7.4</td><td>8.1 or newer</td></tr><tr><td>MySQL / MariaDB</td><td>5.7 / 10.3</td><td>MySQL 8 / MariaDB 11</td></tr><tr><td>Memory</td><td>128 MB</td><td>256 MB or more</td></tr><tr><td>HTTPS</td><td>Required to take live payments</td><td>Always recommended</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Not sure what your hosting has?</p><p>Open <span class="screen-path">Tools → Site Health → Info</span> in WordPress. The PHP and database versions are listed there.</p></div><h2 id="step-1-—-install-the-free-plugin" tabindex="-1">Step 1 — Install the free plugin <a class="header-anchor" href="#step-1-—-install-the-free-plugin" aria-label="Permalink to &quot;Step 1 — Install the free plugin&quot;">​</a></h2><p>The free <strong>Sikshya LMS</strong> plugin gives you a complete LMS — courses, lessons, quizzes, certificates, native checkout (PayPal), coupons, and learner dashboards.</p><p>You have three options:</p><ol class="step-list"><li>The easy way — In WordPress, go to <span class="screen-path">Plugins → Add New</span>, search <strong>Sikshya LMS</strong>, click <strong>Install Now</strong>, then <strong>Activate</strong>.</li><li>If you have the ZIP file — Go to <span class="screen-path">Plugins → Add New → Upload Plugin</span>, choose <code>sikshya.zip</code>, click <strong>Install Now</strong>, then <strong>Activate</strong>.</li><li>The technical way — drop the <code>sikshya/</code> folder into <code>wp-content/plugins/</code> over SFTP, then activate from the Plugins screen.</li></ol><p>When you activate, Sikshya does a one-time setup behind the scenes:</p><ul><li>Creates three new user roles (Sikshya Instructor, Sikshya Student, Sikshya Assistant).</li><li>Creates the database tables for enrollments, orders, certificates, and progress tracking.</li><li>Seeds the default email templates.</li></ul><p>You&#39;ll see a new <strong>Sikshya</strong> item appear in the WordPress admin sidebar.</p><h2 id="step-2-—-install-sikshya-pro" tabindex="-1">Step 2 — Install Sikshya Pro <a class="header-anchor" href="#step-2-—-install-sikshya-pro" aria-label="Permalink to &quot;Step 2 — Install Sikshya Pro&quot;">​</a></h2><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Sikshya Pro is the upgrade plugin</span></div><p class="pro-callout__desc">Sikshya Pro is a separate plugin that unlocks licensed add-ons — Stripe, Razorpay, Mollie, Paystack, Square, Authorize.Net, Bank Transfer gateways; subscriptions; bundles; multi-instructor; gradebook; advanced certificates; drip; prerequisites; webhooks; marketplace; and more. The free plugin must be installed and active first.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">View Sikshya Pro plans →</a></div><p>If you bought a Pro license:</p><ol class="step-list"><li>Make sure the free <strong>Sikshya LMS</strong> plugin is installed and active first. Sikshya Pro depends on it.</li><li>Download <code>sikshya-pro.zip</code> from your Mantrabrain account.</li><li>Go to <span class="screen-path">Plugins → Add New → Upload Plugin</span>, choose the ZIP, <strong>Install</strong>, and <strong>Activate</strong>.</li><li>Open <span class="screen-path">Sikshya → License</span>. Paste your license key into <strong>License key</strong>, then click <strong>Save &amp; activate</strong>.</li><li>Open <span class="screen-path">Sikshya → Add-ons</span> and turn on the add-ons your plan includes.</li></ol><div class="ui-tip"><strong>Tip:</strong> If you cloned the source from Git instead of downloading a release ZIP, run <code>composer install --no-dev --optimize-autoloader</code> from the <code>sikshya-pro</code> folder before activating.</div><h2 id="step-3-—-confirm-sikshya-is-healthy" tabindex="-1">Step 3 — Confirm Sikshya is healthy <a class="header-anchor" href="#step-3-—-confirm-sikshya-is-healthy" aria-label="Permalink to &quot;Step 3 — Confirm Sikshya is healthy&quot;">​</a></h2><p>Run this quick checklist before adding real content.</p><table tabindex="0"><thead><tr><th>Check</th><th>Where</th></tr></thead><tbody><tr><td>The <strong>Sikshya</strong> item appears in the admin sidebar</td><td>Admin sidebar</td></tr><tr><td>Permalinks are not set to <strong>Plain</strong></td><td><span class="screen-path">Settings → Permalinks</span></td></tr><tr><td>Visiting <code>/wp-json/sikshya/v1/</code> returns JSON (not a 404)</td><td>Browser address bar</td></tr><tr><td>Visiting <code>/cart/</code> and <code>/checkout/</code> shows a page (even if empty)</td><td>Front of your site</td></tr><tr><td><strong>License</strong> says <strong>Active</strong> <span class="pro-pill">PRO</span></td><td><span class="screen-path">Sikshya → License</span></td></tr></tbody></table><p>If any of these are red, head over to <a href="/docs/troubleshooting">Troubleshooting</a>.</p><h2 id="multisite" tabindex="-1">Multisite <a class="header-anchor" href="#multisite" aria-label="Permalink to &quot;Multisite&quot;">​</a></h2><p>Sikshya is <strong>Network: true</strong> — it can be activated across a WordPress multisite network.</p><ol class="step-list"><li>Place the <code>sikshya/</code> (and <code>sikshya-pro/</code>) folder into <code>wp-content/plugins/</code>.</li><li>Go to <span class="screen-path">Network Admin → Plugins</span> and choose <strong>Network Activate</strong>.</li><li>Visit each subsite once to let Sikshya create that subsite&#39;s tables and roles.</li><li>Activate the Pro license per subsite (one license slot each by default).</li></ol><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multisite license tools</span></div><p class="pro-callout__desc">If you run a network with many subsites, the <strong>Multisite &amp; network license tools</strong> add-on (Scale plan) helps you manage license slots across the network.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">See Scale plan →</a></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>Run the <a href="/docs/quick-start">Quick start</a> — picks pages, currency, and gateways and gets you to your first published course in under an hour.</li><li>Or jump straight to <a href="/docs/courses">Courses &amp; curriculum</a> to start building.</li></ul>',29)])])}const y=e(i,[["render",r]]);export{u as __pageData,y as default};
